   subroutine CINTgout1e_int1e_cg_irxp(gout, g, idx, envs, gout_empty)
      real(dp), intent(inout) :: gout(0:*)
      real(dp), intent(inout), target :: g(0:)
      integer,  intent(in)    :: idx(0:*)
      type(cint_env_vars), intent(in) :: envs
      integer,  intent(in)    :: gout_empty
      integer  :: nf, ix, iy, iz, n
      integer  :: g0, g1, g2, g3
      real(dp), pointer, contiguous :: g0p(:), g1p(:), g2p(:), g3p(:)
      real(dp) :: s(0:8)
      real(dp) :: drj(0:2)

      drj = envs%rj - envs%env(PTR_COMMON_ORIG:PTR_COMMON_ORIG+2)
      nf = envs%nf
      g0 = 0
      g1 = g0 + envs%g_size * 3
      g2 = g1 + envs%g_size * 3
      g3 = g2 + envs%g_size * 3
      call cint_nabla1j_1e(g, g1, g0, envs%i_l+0, envs%j_l+0, 0, envs)
      call cint_x1j_1e(g, g2, g0, drj, envs%i_l+0, envs%j_l+1, 0, envs)
      call cint_nabla1j_1e(g, g3, g2, envs%i_l+0, envs%j_l+0, 0, envs)
      g0p(0:) => g(g0:)
      g1p(0:) => g(g1:)
      g2p(0:) => g(g2:)
      g3p(0:) => g(g3:)

      do n = 0, nf - 1
         ix = idx(0+n*3)
         iy = idx(1+n*3)
         iz = idx(2+n*3)
         s(0) = + g3p(ix+0)*g0p(iy+0)*g0p(iz+0)
         s(1) = + g2p(ix+0)*g1p(iy+0)*g0p(iz+0)
         s(2) = + g2p(ix+0)*g0p(iy+0)*g1p(iz+0)
         s(3) = + g1p(ix+0)*g2p(iy+0)*g0p(iz+0)
         s(4) = + g0p(ix+0)*g3p(iy+0)*g0p(iz+0)
         s(5) = + g0p(ix+0)*g2p(iy+0)*g1p(iz+0)
         s(6) = + g1p(ix+0)*g0p(iy+0)*g2p(iz+0)
         s(7) = + g0p(ix+0)*g1p(iy+0)*g2p(iz+0)
         s(8) = + g0p(ix+0)*g0p(iy+0)*g3p(iz+0)
         if (gout_empty /= 0) then
            gout(n*3+0) = + s(5) - s(7)
            gout(n*3+1) = + s(6) - s(2)
            gout(n*3+2) = + s(1) - s(3)
         else
            gout(n*3+0) = gout(n*3+0) + ( + s(5) - s(7) )
            gout(n*3+1) = gout(n*3+1) + ( + s(6) - s(2) )
            gout(n*3+2) = gout(n*3+2) + ( + s(1) - s(3) )
         end if
      end do
   end subroutine CINTgout1e_int1e_cg_irxp

