   function int1e_z_sph(out, dims, shls, atm, natm, bas, nbas, env, ws) &
         result(has_value)
      real(dp), intent(inout) :: out(0:)
      integer,  intent(in)    :: dims(0:), shls(0:), atm(0:), bas(0:)
