      type(cint_env_vars), intent(in) :: envs
      integer,  intent(in)    :: gout_empty
      integer  :: nf, ix, iy, iz, n
      integer  :: g0, g1
      real(dp), pointer, contiguous :: g0p(:), g1p(:)
      real(dp) :: s(0:2)
      real(dp) :: drj(0:2)

      drj = envs%rj - envs%env(PTR_COMMON_ORIG:PTR_COMMON_ORIG+2)
      nf = envs%nf
      g0 = 0
      g1 = g0 + envs%g_size * 3
      call cint_x1j_1e(g, g1, g0, drj, envs%i_l+0, envs%j_l+0, 0, envs)
      g0p(0:) => g(g0:)
      g1p(0:) => g(g1:)

      do n = 0, nf - 1
         ix = idx(0+n*3)
         iy = idx(1+n*3)
         iz = idx(2+n*3)
         s(0) = + g1p(ix+0)*g0p(iy+0)*g0p(iz+0)
