         s(9) = + g11p(ix+0)*g4p(iy+0)*g0p(iz+0)
         s(10) = + g10p(ix+0)*g5p(iy+0)*g0p(iz+0)
         s(11) = + g10p(ix+0)*g4p(iy+0)*g1p(iz+0)
         s(12) = + g9p(ix+0)*g6p(iy+0)*g0p(iz+0)
         s(13) = + g8p(ix+0)*g7p(iy+0)*g0p(iz+0)
         s(14) = + g8p(ix+0)*g6p(iy+0)*g1p(iz+0)
         s(15) = + g9p(ix+0)*g4p(iy+0)*g2p(iz+0)
         s(16) = + g8p(ix+0)*g5p(iy+0)*g2p(iz+0)
         s(17) = + g8p(ix+0)*g4p(iy+0)*g3p(iz+0)
         s(18) = + g11p(ix+0)*g0p(iy+0)*g4p(iz+0)
         s(19) = + g10p(ix+0)*g1p(iy+0)*g4p(iz+0)
         s(20) = + g10p(ix+0)*g0p(iy+0)*g5p(iz+0)
         s(21) = + g9p(ix+0)*g2p(iy+0)*g4p(iz+0)
         s(22) = + g8p(ix+0)*g3p(iy+0)*g4p(iz+0)
         s(23) = + g8p(ix+0)*g2p(iy+0)*g5p(iz+0)
