   subroutine CINTgout1e_int1e_rrr(gout, g, idx, envs, gout_empty)
      real(dp), intent(inout) :: gout(0:*)
      real(dp), intent(inout), target :: g(0:)
      integer,  intent(in)    :: idx(0:*)
      type(cint_env_vars), intent(in) :: envs
      integer,  intent(in)    :: gout_empty
      integer  :: nf, ix, iy, iz, n
      integer  :: g0, g1, g2, g3, g4, g5, g6, g7
      real(dp), pointer, contiguous :: g0p(:), g1p(:), g2p(:), g3p(:), g4p(:), g5p(:)
      real(dp), pointer, contiguous :: g6p(:), g7p(:)
      real(dp) :: s(0:26)
      real(dp) :: drj(0:2)

      drj = envs%rj - envs%env(PTR_COMMON_ORIG:PTR_COMMON_ORIG+2)
      nf = envs%nf
      g0 = 0
      g1 = g0 + envs%g_size * 3
      g2 = g1 + envs%g_size * 3
      g3 = g2 + envs%g_size * 3
      g4 = g3 + envs%g_size * 3
      g5 = g4 + envs%g_size * 3
      g6 = g5 + envs%g_size * 3
      g7 = g6 + envs%g_size * 3
      call cint_x1j_1e(g, g1, g0, drj, envs%i_l+0, envs%j_l+0, 0, envs)
      call cint_x1j_1e(g, g2, g0, drj, envs%i_l+0, envs%j_l+1, 0, envs)
      call cint_x1j_1e(g, g3, g2, drj, envs%i_l+0, envs%j_l+0, 0, envs)
      call cint_x1j_1e(g, g4, g0, drj, envs%i_l+0, envs%j_l+2, 0, envs)
      call cint_x1j_1e(g, g5, g4, drj, envs%i_l+0, envs%j_l+0, 0, envs)
      call cint_x1j_1e(g, g6, g4, drj, envs%i_l+0, envs%j_l+1, 0, envs)
      call cint_x1j_1e(g, g7, g6, drj, envs%i_l+0, envs%j_l+0, 0, envs)
      g0p(0:) => g(g0:)
      g1p(0:) => g(g1:)
      g2p(0:) => g(g2:)
      g3p(0:) => g(g3:)
      g4p(0:) => g(g4:)
      g5p(0:) => g(g5:)
      g6p(0:) => g(g6:)
      g7p(0:) => g(g7:)

      do n = 0, nf - 1
         ix = idx(0+n*3)
         iy = idx(1+n*3)
         iz = idx(2+n*3)
         s(0) = + g7p(ix+0)*g0p(iy+0)*g0p(iz+0)
         s(1) = + g6p(ix+0)*g1p(iy+0)*g0p(iz+0)
         s(2) = + g6p(ix+0)*g0p(iy+0)*g1p(iz+0)
         s(3) = + g5p(ix+0)*g2p(iy+0)*g0p(iz+0)
         s(4) = + g4p(ix+0)*g3p(iy+0)*g0p(iz+0)
         s(5) = + g4p(ix+0)*g2p(iy+0)*g1p(iz+0)
         s(6) = + g5p(ix+0)*g0p(iy+0)*g2p(iz+0)
         s(7) = + g4p(ix+0)*g1p(iy+0)*g2p(iz+0)
         s(8) = + g4p(ix+0)*g0p(iy+0)*g3p(iz+0)
         s(9) = + g3p(ix+0)*g4p(iy+0)*g0p(iz+0)
         s(10) = + g2p(ix+0)*g5p(iy+0)*g0p(iz+0)
         s(11) = + g2p(ix+0)*g4p(iy+0)*g1p(iz+0)
         s(12) = + g1p(ix+0)*g6p(iy+0)*g0p(iz+0)
         s(13) = + g0p(ix+0)*g7p(iy+0)*g0p(iz+0)
         s(14) = + g0p(ix+0)*g6p(iy+0)*g1p(iz+0)
         s(15) = + g1p(ix+0)*g4p(iy+0)*g2p(iz+0)
         s(16) = + g0p(ix+0)*g5p(iy+0)*g2p(iz+0)
