            gout(n*9+0) = + s(0)
            gout(n*9+1) = + s(1)
            gout(n*9+2) = + s(2)
            gout(n*9+3) = + s(3)
            gout(n*9+4) = + s(4)
            gout(n*9+5) = + s(5)
            gout(n*9+6) = + s(6)
            gout(n*9+7) = + s(7)
            gout(n*9+8) = + s(8)
         else
            gout(n*9+0) = gout(n*9+0) + ( + s(0) )
            gout(n*9+1) = gout(n*9+1) + ( + s(1) )
            gout(n*9+2) = gout(n*9+2) + ( + s(2) )
            gout(n*9+3) = gout(n*9+3) + ( + s(3) )
            gout(n*9+4) = gout(n*9+4) + ( + s(4) )
