            gout(n*9+2) = gout(n*9+2) + ( + c(3)*s(63) - c(6)*s(36) - c(4)*s(54) + c(7)*s(27) + c(3)*s(67) &
                        - c(6)*s(40) - c(4)*s(58) + c(7)*s(31) + c(3)*s(71) - c(6)*s(44) - c(4)*s(62) &
