                        - c(0)*s(67) - c(7)*s(4) + c(1)*s(58) + c(6)*s(17) - c(0)*s(71) - c(7)*s(8) &
                        + c(1)*s(62) )
            gout(n*9+6) = gout(n*9+6) + ( + c(1)*s(45) - c(4)*s(18) - c(2)*s(36) + c(5)*s(9) + c(1)*s(49) &
