   subroutine CINTgout1e_int1e_ggnuc(gout, g, idx, envs, gout_empty)
      real(dp), intent(inout) :: gout(0:*)
      real(dp), intent(inout), target :: g(0:)
      integer,  intent(in)    :: idx(0:*)
      type(cint_env_vars), intent(in) :: envs
      integer,  intent(in)    :: gout_empty
      integer  :: nf, nroots, ix, iy, iz, i, n
      integer  :: g0, g1, g2, g3
      real(dp), pointer, contiguous :: g0p(:), g1p(:), g2p(:), g3p(:)
      real(dp) :: s(0:8)
      real(dp) :: rirj(0:2)
      real(dp) :: c(0:8)

      rirj = envs%ri - envs%rj
      c(0) = 1.0_dp * rirj(0) * rirj(0)
      c(1) = 1.0_dp * rirj(0) * rirj(1)
      c(2) = 1.0_dp * rirj(0) * rirj(2)
      c(3) = 1.0_dp * rirj(1) * rirj(0)
      c(4) = 1.0_dp * rirj(1) * rirj(1)
      c(5) = 1.0_dp * rirj(1) * rirj(2)
      c(6) = 1.0_dp * rirj(2) * rirj(0)
      c(7) = 1.0_dp * rirj(2) * rirj(1)
      c(8) = 1.0_dp * rirj(2) * rirj(2)
      nf = envs%nf
      nroots = envs%nrys_roots
      g0 = 0
      g1 = g0 + envs%g_size * 3
      g2 = g1 + envs%g_size * 3
      g3 = g2 + envs%g_size * 3
      call cint_x1j_2e(g, g1, g0, envs%rj, envs%i_l+0, envs%j_l+0, 0, 0, envs)
      call cint_x1j_2e(g, g2, g0, envs%rj, envs%i_l+0, envs%j_l+1, 0, 0, envs)
      call cint_x1j_2e(g, g3, g2, envs%rj, envs%i_l+0, envs%j_l+0, 0, 0, envs)
      g0p(0:) => g(g0:)
      g1p(0:) => g(g1:)
      g2p(0:) => g(g2:)
      g3p(0:) => g(g3:)

      do n = 0, nf - 1
         ix = idx(0+n*3)
         iy = idx(1+n*3)
         iz = idx(2+n*3)
         s = 0.0_dp
         do i = 0, nroots - 1
               s(0) = s(0) + g3p(ix+i) * g0p(iy+i) * g0p(iz+i)
               s(1) = s(1) + g2p(ix+i) * g1p(iy+i) * g0p(iz+i)
               s(2) = s(2) + g2p(ix+i) * g0p(iy+i) * g1p(iz+i)
               s(3) = s(3) + g1p(ix+i) * g2p(iy+i) * g0p(iz+i)
               s(4) = s(4) + g0p(ix+i) * g3p(iy+i) * g0p(iz+i)
               s(5) = s(5) + g0p(ix+i) * g2p(iy+i) * g1p(iz+i)
               s(6) = s(6) + g1p(ix+i) * g0p(iy+i) * g2p(iz+i)
               s(7) = s(7) + g0p(ix+i) * g1p(iy+i) * g2p(iz+i)
               s(8) = s(8) + g0p(ix+i) * g0p(iy+i) * g3p(iz+i)
         end do
         if (gout_empty /= 0) then
            gout(n*9+0) = - c(4)*s(8) + 2*c(5)*s(7) - c(8)*s(4)
            gout(n*9+1) = - c(5)*s(6) + c(8)*s(3) + c(3)*s(8) - c(6)*s(5)
            gout(n*9+2) = - c(3)*s(7) + c(6)*s(4) + c(4)*s(6) - c(7)*s(3)
            gout(n*9+3) = - c(7)*s(2) + c(1)*s(8) + c(8)*s(1) - c(2)*s(7)
            gout(n*9+4) = - c(8)*s(0) + 2*c(6)*s(2) - c(0)*s(8)
            gout(n*9+5) = - c(6)*s(1) + c(0)*s(7) + c(7)*s(0) - c(1)*s(6)
            gout(n*9+6) = - c(1)*s(5) + c(4)*s(2) + c(2)*s(4) - c(5)*s(1)
            gout(n*9+7) = - c(2)*s(3) + c(5)*s(0) + c(0)*s(5) - c(3)*s(2)
            gout(n*9+8) = - c(0)*s(4) + 2*c(1)*s(3) - c(4)*s(0)
         else
            gout(n*9+0) = gout(n*9+0) + ( - c(4)*s(8) + 2*c(5)*s(7) - c(8)*s(4) )
            gout(n*9+1) = gout(n*9+1) + ( - c(5)*s(6) + c(8)*s(3) + c(3)*s(8) - c(6)*s(5) )
            gout(n*9+2) = gout(n*9+2) + ( - c(3)*s(7) + c(6)*s(4) + c(4)*s(6) - c(7)*s(3) )
            gout(n*9+3) = gout(n*9+3) + ( - c(7)*s(2) + c(1)*s(8) + c(8)*s(1) - c(2)*s(7) )
            gout(n*9+4) = gout(n*9+4) + ( - c(8)*s(0) + 2*c(6)*s(2) - c(0)*s(8) )
            gout(n*9+5) = gout(n*9+5) + ( - c(6)*s(1) + c(0)*s(7) + c(7)*s(0) - c(1)*s(6) )
            gout(n*9+6) = gout(n*9+6) + ( - c(1)*s(5) + c(4)*s(2) + c(2)*s(4) - c(5)*s(1) )
            gout(n*9+7) = gout(n*9+7) + ( - c(2)*s(3) + c(5)*s(0) + c(0)*s(5) - c(3)*s(2) )
            gout(n*9+8) = gout(n*9+8) + ( - c(0)*s(4) + 2*c(1)*s(3) - c(4)*s(0) )
         end if
      end do
   end subroutine CINTgout1e_int1e_ggnuc

