   function int1e_ggnuc_spinor(out, dims, shls, atm, natm, bas, nbas, env, ws) &
         result(has_value)
      complex(dp), intent(inout) :: out(0:)
      integer,  intent(in)    :: dims(0:), shls(0:), natm, nbas
      integer,  target        :: atm(0:), bas(0:)
      real(dp), target        :: env(0:)
      type(cint_ws), intent(inout) :: ws
      logical :: has_value
      type(cint_env_vars) :: envs
      integer, parameter :: ng(0:7) = [0, 2, 0, 0, 2, 1, 0, 9]

      call cint_init_int1e_envvars(envs, ng, shls, atm, natm, bas, nbas, env)
      envs%f_gout => CINTgout1e_int1e_ggnuc
      envs%common_factor = envs%common_factor * (0.25_dp)
      has_value = cint_1e_spinor_drv(out, dims, envs, ws, .false., .false., 2)
   end function int1e_ggnuc_spinor

   ! <i|G R CROSS P |j>
   subroutine int1e_grjxp_optimizer(opt, atm, natm, bas, nbas, env)
      type(cint_opt_t), intent(inout) :: opt
      integer,  intent(in) :: natm, nbas
      integer,  intent(in) :: atm(0:), bas(0:)
      real(dp), intent(in) :: env(0:)
      integer, parameter :: ng(0:7) = [0, 3, 0, 0, 3, 1, 1, 9]
      call cint_all_1e_optimizer(opt, ng, atm, natm, bas, nbas, env)
   end subroutine int1e_grjxp_optimizer

   subroutine CINTgout1e_int1e_grjxp(gout, g, idx, envs, gout_empty)
      real(dp), intent(inout) :: gout(0:*)
      real(dp), intent(inout), target :: g(0:)
      integer,  intent(in)    :: idx(0:*)
      type(cint_env_vars), intent(in) :: envs
      integer,  intent(in)    :: gout_empty
      integer  :: nf, ix, iy, iz, n
      integer  :: g0, g1, g2, g3, g4, g5, g6, g7
      real(dp), pointer, contiguous :: g0p(:), g1p(:), g2p(:), g3p(:), g4p(:), g5p(:)
      real(dp), pointer, contiguous :: g6p(:), g7p(:)
      real(dp) :: s(0:26)
      real(dp) :: rirj(0:2)
      real(dp) :: c(0:2)

      rirj = envs%ri - envs%rj
      c(0) = 1.0_dp * rirj(0)
      c(1) = 1.0_dp * rirj(1)
      c(2) = 1.0_dp * rirj(2)
      nf = envs%nf
      g0 = 0
      g1 = g0 + envs%g_size * 3
      g2 = g1 + envs%g_size * 3
      g3 = g2 + envs%g_size * 3
      g4 = g3 + envs%g_size * 3
      g5 = g4 + envs%g_size * 3
      g6 = g5 + envs%g_size * 3
      g7 = g6 + envs%g_size * 3
      call cint_nabla1j_1e(g, g1, g0, envs%i_l+0, envs%j_l+0, 0, envs)
      g2 = g0 + envs%g_stride_j
      call cint_nabla1j_1e(g, g3, g2, envs%i_l+0, envs%j_l+0, 0, envs)
      call cint_x1j_1e(g, g4, g0, envs%rj, envs%i_l+0, envs%j_l+2, 0, envs)
      call cint_nabla1j_1e(g, g5, g4, envs%i_l+0, envs%j_l+0, 0, envs)
      g6 = g4 + envs%g_stride_j
      call cint_nabla1j_1e(g, g7, g6, envs%i_l+0, envs%j_l+0, 0, envs)
      g0p(0:) => g(g0:)
      g1p(0:) => g(g1:)
      g2p(0:) => g(g2:)
      g3p(0:) => g(g3:)
      g4p(0:) => g(g4:)
      g5p(0:) => g(g5:)
      g6p(0:) => g(g6:)
      g7p(0:) => g(g7:)

      do n = 0, nf - 1
         ix = idx(0+n*3)
         iy = idx(1+n*3)
         iz = idx(2+n*3)
         s(0) = + g7p(ix+0)*g0p(iy+0)*g0p(iz+0)
         s(1) = + g6p(ix+0)*g1p(iy+0)*g0p(iz+0)
         s(2) = + g6p(ix+0)*g0p(iy+0)*g1p(iz+0)
         s(3) = + g5p(ix+0)*g2p(iy+0)*g0p(iz+0)
         s(4) = + g4p(ix+0)*g3p(iy+0)*g0p(iz+0)
         s(5) = + g4p(ix+0)*g2p(iy+0)*g1p(iz+0)
         s(6) = + g5p(ix+0)*g0p(iy+0)*g2p(iz+0)
         s(7) = + g4p(ix+0)*g1p(iy+0)*g2p(iz+0)
         s(8) = + g4p(ix+0)*g0p(iy+0)*g3p(iz+0)
         s(9) = + g3p(ix+0)*g4p(iy+0)*g0p(iz+0)
         s(10) = + g2p(ix+0)*g5p(iy+0)*g0p(iz+0)
         s(11) = + g2p(ix+0)*g4p(iy+0)*g1p(iz+0)
         s(12) = + g1p(ix+0)*g6p(iy+0)*g0p(iz+0)
         s(13) = + g0p(ix+0)*g7p(iy+0)*g0p(iz+0)
         s(14) = + g0p(ix+0)*g6p(iy+0)*g1p(iz+0)
         s(15) = + g1p(ix+0)*g4p(iy+0)*g2p(iz+0)
         s(16) = + g0p(ix+0)*g5p(iy+0)*g2p(iz+0)
         s(17) = + g0p(ix+0)*g4p(iy+0)*g3p(iz+0)
         s(18) = + g3p(ix+0)*g0p(iy+0)*g4p(iz+0)
         s(19) = + g2p(ix+0)*g1p(iy+0)*g4p(iz+0)
         s(20) = + g2p(ix+0)*g0p(iy+0)*g5p(iz+0)
         s(21) = + g1p(ix+0)*g2p(iy+0)*g4p(iz+0)
         s(22) = + g0p(ix+0)*g3p(iy+0)*g4p(iz+0)
         s(23) = + g0p(ix+0)*g2p(iy+0)*g5p(iz+0)
         s(24) = + g1p(ix+0)*g0p(iy+0)*g6p(iz+0)
         s(25) = + g0p(ix+0)*g1p(iy+0)*g6p(iz+0)
         s(26) = + g0p(ix+0)*g0p(iy+0)*g7p(iz+0)
         if (gout_empty /= 0) then
            gout(n*9+0) = + c(1)*s(23) - c(2)*s(14) - c(1)*s(25) + c(2)*s(16)
            gout(n*9+1) = + c(1)*s(24) - c(2)*s(15) - c(1)*s(20) + c(2)*s(11)
            gout(n*9+2) = + c(1)*s(19) - c(2)*s(10) - c(1)*s(21) + c(2)*s(12)
            gout(n*9+3) = + c(2)*s(5) - c(0)*s(23) - c(2)*s(7) + c(0)*s(25)
            gout(n*9+4) = + c(2)*s(6) - c(0)*s(24) - c(2)*s(2) + c(0)*s(20)
            gout(n*9+5) = + c(2)*s(1) - c(0)*s(19) - c(2)*s(3) + c(0)*s(21)
            gout(n*9+6) = + c(0)*s(14) - c(1)*s(5) - c(0)*s(16) + c(1)*s(7)
            gout(n*9+7) = + c(0)*s(15) - c(1)*s(6) - c(0)*s(11) + c(1)*s(2)
            gout(n*9+8) = + c(0)*s(10) - c(1)*s(1) - c(0)*s(12) + c(1)*s(3)
         else
            gout(n*9+0) = gout(n*9+0) + ( + c(1)*s(23) - c(2)*s(14) - c(1)*s(25) + c(2)*s(16) )
            gout(n*9+1) = gout(n*9+1) + ( + c(1)*s(24) - c(2)*s(15) - c(1)*s(20) + c(2)*s(11) )
            gout(n*9+2) = gout(n*9+2) + ( + c(1)*s(19) - c(2)*s(10) - c(1)*s(21) + c(2)*s(12) )
            gout(n*9+3) = gout(n*9+3) + ( + c(2)*s(5) - c(0)*s(23) - c(2)*s(7) + c(0)*s(25) )
            gout(n*9+4) = gout(n*9+4) + ( + c(2)*s(6) - c(0)*s(24) - c(2)*s(2) + c(0)*s(20) )
            gout(n*9+5) = gout(n*9+5) + ( + c(2)*s(1) - c(0)*s(19) - c(2)*s(3) + c(0)*s(21) )
            gout(n*9+6) = gout(n*9+6) + ( + c(0)*s(14) - c(1)*s(5) - c(0)*s(16) + c(1)*s(7) )
            gout(n*9+7) = gout(n*9+7) + ( + c(0)*s(15) - c(1)*s(6) - c(0)*s(11) + c(1)*s(2) )
            gout(n*9+8) = gout(n*9+8) + ( + c(0)*s(10) - c(1)*s(1) - c(0)*s(12) + c(1)*s(3) )
         end if
      end do
   end subroutine CINTgout1e_int1e_grjxp

   function int1e_grjxp_cart(out, dims, shls, atm, natm, bas, nbas, env, ws) &
         result(has_value)
      real(dp), intent(inout) :: out(0:)
      integer,  intent(in)    :: dims(0:), shls(0:), atm(0:), bas(0:)
