   ! <i|RINV |j>
   subroutine int1e_rinv_optimizer(opt, atm, natm, bas, nbas, env)
      type(cint_opt_t), intent(inout) :: opt
      integer,  intent(in) :: natm, nbas
      integer,  intent(in) :: atm(0:), bas(0:)
      real(dp), intent(in) :: env(0:)
      integer, parameter :: ng(0:7) = [0, 0, 0, 0, 0, 1, 0, 1]
      call cint_all_1e_optimizer(opt, ng, atm, natm, bas, nbas, env)
   end subroutine int1e_rinv_optimizer

   subroutine CINTgout1e_int1e_rinv(gout, g, idx, envs, gout_empty)
      real(dp), intent(inout) :: gout(0:*)
      real(dp), intent(inout), target :: g(0:)
      integer,  intent(in)    :: idx(0:*)
      type(cint_env_vars), intent(in) :: envs
      integer,  intent(in)    :: gout_empty
      integer  :: nf, nroots, ix, iy, iz, i, n
      integer  :: g0
      real(dp), pointer, contiguous :: g0p(:)
      real(dp) :: s(0:0)

      nf = envs%nf
      nroots = envs%nrys_roots
      g0 = 0
      g0p(0:) => g(g0:)

      do n = 0, nf - 1
         ix = idx(0+n*3)
         iy = idx(1+n*3)
         iz = idx(2+n*3)
         s = 0.0_dp
         do i = 0, nroots - 1
               s(0) = s(0) + g0p(ix+i) * g0p(iy+i) * g0p(iz+i)
         end do
         if (gout_empty /= 0) then
            gout(n*1+0) = + s(0)
         else
            gout(n*1+0) = gout(n*1+0) + ( + s(0) )
         end if
      end do
   end subroutine CINTgout1e_int1e_rinv

