   end subroutine int1e_drinv_optimizer

   subroutine CINTgout1e_int1e_drinv(gout, g, idx, envs, gout_empty)
      real(dp), intent(inout) :: gout(0:*)
      real(dp), intent(inout), target :: g(0:)
      integer,  intent(in)    :: idx(0:*)
      type(cint_env_vars), intent(in) :: envs
      integer,  intent(in)    :: gout_empty
      integer  :: nf, nroots, ix, iy, iz, i, n
      integer  :: g0, g1, g2
      real(dp), pointer, contiguous :: g0p(:), g1p(:), g2p(:)
      real(dp) :: s(0:2)

      nf = envs%nf
      nroots = envs%nrys_roots
      g0 = 0
      g1 = g0 + envs%g_size * 3
      g2 = g1 + envs%g_size * 3
      call cint_nabla1j_2e(g, g1, g0, envs%i_l+0, envs%j_l+0, 0, 0, envs)
      call cint_nabla1i_2e(g, g2, g0, envs%i_l+0, envs%j_l+0, 0, 0, envs)
      do ix = 0, envs%g_size*3 - 1
         g(g1+ix) = g(g1+ix) + g(g2+ix)
      end do
      g0p(0:) => g(g0:)
      g1p(0:) => g(g1:)
      g2p(0:) => g(g2:)

      do n = 0, nf - 1
         ix = idx(0+n*3)
         iy = idx(1+n*3)
         iz = idx(2+n*3)
         s = 0.0_dp
         do i = 0, nroots - 1
               s(0) = s(0) + g1p(ix+i) * g0p(iy+i) * g0p(iz+i)
               s(1) = s(1) + g0p(ix+i) * g1p(iy+i) * g0p(iz+i)
               s(2) = s(2) + g0p(ix+i) * g0p(iy+i) * g1p(iz+i)
         end do
         if (gout_empty /= 0) then
            gout(n*3+0) = + s(0)
            gout(n*3+1) = + s(1)
            gout(n*3+2) = + s(2)
         else
            gout(n*3+0) = gout(n*3+0) + ( + s(0) )
            gout(n*3+1) = gout(n*3+1) + ( + s(1) )
            gout(n*3+2) = gout(n*3+2) + ( + s(2) )
         end if
      end do
   end subroutine CINTgout1e_int1e_drinv

